graphql.example:
type Query {
  order(id: ID!): Order
  orders(first: Int = 20): [Order!]!
}

type Mutation {
  createOrder(input: OrderInput!): Order!
}

enum Status { OPEN CLOSED }

input OrderInput {
  status: Status
  note: String
}

type Order {
  id: ID!
  status: Status!
  totalCents: Int!
  note: String
}

protobuf.example:
syntax = "proto3";
package shop.v1;

enum Status {
  STATUS_UNSPECIFIED = 0;
  OPEN = 1;
  CLOSED = 2;
}

message Order {
  string order_id = 1;
  int64 total_cents = 2;
  Status status = 3;
  repeated string tags = 4;
  string note = 5;
}
